from pathlib import Path
import json, subprocess

def replace(path,old,new):
 p=Path(path);s=p.read_text()
 if s.count(old)!=1:raise RuntimeError(f'{path}: expected one occurrence of {old[:100]!r}, got {s.count(old)}')
 p.write_text(s.replace(old,new))

# Preserve duplicate rejection even when slow-path source writes flush before a later edit.
replace('apps/server/src/history-preparation.ts', '    const audience = new Set<string>();\n    for (const event of changed)', '''    const changedIds = new Set<string>();
    for (const event of changed) {
      if (changedIds.has(event.id)) throw new Error('Duplicate changed history event identity.');
      changedIds.add(event.id);
    }
    const audience = new Set<string>();
    for (const event of changed)''')
# Moving SQLite off-thread must not make heap-only metrics look like whole-process memory.
replace('apps/server/src/sqlite-database.ts','      elapsedMs: number;','      elapsedMs: number;\n      heapUsedBytes?: number;')
replace('apps/server/src/sqlite-database.ts', "      recordDuration('sqlite.workerExecution', reply.elapsedMs);", "      recordDuration('sqlite.workerExecution', reply.elapsedMs);\n      if (reply.heapUsedBytes !== undefined) gaugeMetric('sqlite.workerHeapUsedBytes', reply.heapUsedBytes);")
replace('apps/server/src/sqlite-worker.mjs','const MAX_STATEMENTS = 128;','const MAX_STATEMENTS = 128;\nlet lastMemoryReport = 0;')
p=Path('apps/server/src/sqlite-worker.mjs');s=p.read_text();old="  parentPort.postMessage({ kind: 'result', id, value, error, elapsedMs: performance.now() - started });"
if old not in s:
 # Prettier expands the current message; locate only the fixed reply body.
 start=s.index('  parentPort.postMessage({');end=s.index("  if (operation === 'close')",start)
else:start=s.index(old);end=start+len(old)+1
s=s[:start]+'''  const now = performance.now();
  const memory = now - lastMemoryReport >= 1000;
  if (memory) lastMemoryReport = now;
  parentPort.postMessage({
    kind: 'result', id, value, error, elapsedMs: now - started,
    ...(memory ? { heapUsedBytes: process.memoryUsage().heapUsed } : {}),
  });
'''+s[end:];p.write_text(s)
replace('apps/server/src/performance.ts', "    gaugeMetric('process.heapUsedBytes', process.memoryUsage().heapUsed);", "    const memory = process.memoryUsage();\n    gaugeMetric('process.heapUsedBytes', memory.heapUsed);\n    gaugeMetric('process.rssBytes', memory.rss);")
replace('scripts/performance/profile-server.mjs', '        heapUsedBytes: process.memoryUsage().heapUsed,', '        heapUsedBytes: process.memoryUsage().heapUsed,\n        rssBytes: process.memoryUsage().rss,')

p=Path('docs/maintainers/performance.md');s=p.read_text()
s=s.replace('PF04/PF06/PF07/PF10 remain conditional without evidence justifying their extra mechanisms.', 'PF10 now includes measured local SQLite worker isolation; additional simulation/serialization workers remain conditional. PF04/PF06/PF07 remain conditional without evidence justifying their extra mechanisms.')
s=s.replace('PF04/PF07/PF10 remain gated on residual measured cost.', 'PF04/PF07 and additional PF10 worker roles remain gated on residual measured cost; the local SQLite role is implemented below.')
s=s.replace("Dependencies: PF03/PF05; measured residual event-loop CPU or unavoidable confirmation RTT.\n", "Dependencies: PF03/PF05; measured residual event-loop CPU or unavoidable confirmation RTT.\n\n- [x] Isolate the measured synchronous local SQLite connection in a long-lived worker through the existing transaction lane, with bounded admission and statement reuse. Preserve COMMIT acknowledgement, unrelated-read isolation and explicit recovery after worker failure. See [SQLite execution contract](../performance.md#sqlite-worker-isolation) and [qualification](../verification.md#dense-persistence-implementation). This does not complete simulation-worker or browser-prediction work.\n")
s=s.replace('- [ ] Investigate the remaining dense first-commit cost through PF00/PF01: source/awareness construction, immutable state finalization, history encoding and SQLite transaction work must be attributed separately. Preserve individual evidence identity, privacy, revocation and atomicity. Do not yield a shared SQLite transaction to readers that could observe partial writes.', '- [x] Attribute dense first-commit history lookup/construction and SQL transaction boundaries; implement bounded source buffers and local worker isolation without exposing partial writes. Residual native state construction, finalization, changed-awareness scans and dense command latency remain open under DP06/PF03/PF08.')
s=s.replace('- [ ] DP06 — Record matched native/history/full-server measurements and recovery exercises, including mature history and bounded high-command-count work. Long soaks, PostgreSQL, browser and live cognition remain separate qualification.', '- [x] DP06 — Record matched native/history/full-server measurements, worker recovery, dense warm execution and 2,401-command 1x / 1,200-command 8x small-server runs. Required history projection/edit/forgetting/rollback is equivalent on disposable SQLite and PostgreSQL; full PostgreSQL server, browser, live cognition and 30-minute soaks remain unqualified.')
s=s.replace('- [ ] DP05 — Correct measured overload being misclassified as suspension using explicit attribution, without permitting catch-up after real suspension.', '- [ ] DP05 — Qualify an independent liveness/clock signal before changing the remaining callback-gap heuristic. SQLite isolation removed excluded gaps in the measured dense run, but arbitrary multi-second native/encoding stalls can still be misclassified. Do not substitute CPU guesses or treat this as a completed clock-policy fix.')
s+='''\n### Remaining density boundary\n\n- [ ] Attribute and reduce dense native acquisition/finalization and observation/projection rebuilding under actual interleaved commands. A worker improved event-loop isolation but did not improve dense confirmed-command tails or simulation throughput; do not declare population capacity from the small-world result.\n- [ ] Profile affected-actor active-awareness index/edit scans and flat-array copy-on-write under growing history before paged active evidence or a new retained-state representation. Any grouping must retain exact source identities, audience, event-time knowledge and revocation. No lossless paging or asynchronous authoritative history projection is implemented by the bounded SQL-row buffer.\n- [ ] Complete longer repeated SQLite/PostgreSQL full-server cases, 30-minute soaks, browser timing, slow readers and explicit no-network cognition/maintenance work. The PostgreSQL history fixture alone is not end-to-end acceptance.\n'''
